// KFB stone arch bridge FIELD (bridge02) - hand-written layout code, not generated by the
// img2threejs factory generator (it cannot express wedges, chord-cut spandrel blocks,
// per-vertex tone or merged meshes; see TEST_REPORT.md).
//
// Units: KFB K2 lab units (figure H = 3.64). y up, origin = deck centre (deck top y = 0).
// x = bridge axis (span direction), z = across the deck.
//
// Every block is a "clay block": a 24-vertex / 44-triangle chamfered hexahedron whose
// vertices carry the (slightly pillow-tilted) face normal, so the per-pixel normal
// interpolation across the chamfer reads as a rounded clay edge. Blocks are mapped
// trilinearly onto 8 arbitrary corners, which gives tapered voussoirs and chord-cut
// spandrel blocks for free. All parts of one family are merged into a single
// BufferGeometry with vertex colours; all clay parts share ONE material.
import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';

type V3 = [number, number, number];

export const KFB_BRIDGE_PALETTE = {
  masonry: ['#e6d4b5', '#d1ba99', '#b29c7d', '#9e856b'],
  rock: ['#aaa59b', '#918c83'],
  grass: ['#94b834', '#7fa42b'],
  lanternGreen: '#2f4a3a',
  lanternLight: '#ffd27a',
};

export type BridgeFieldOptions = {
  span?: number; // clear opening (lab)
  riseRatio?: number; // rise / span
  halfWidth?: number; // half deck width incl. parapets
  abutLen?: number; // abutment length each side, measured from springing
  seed?: number;
  castShadow?: boolean;
  receiveShadow?: boolean;
};

function mulberry32(a: number) {
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

class Acc {
  pos: number[] = []; nor: number[] = []; col: number[] = []; idx: number[] = [];
  get vcount() { return this.pos.length / 3; }
  build(): THREE.BufferGeometry {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nor, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
    g.setIndex(this.idx);
    g.computeBoundingBox(); g.computeBoundingSphere();
    return g;
  }
  /** append a geometry through a per-vertex warp (position, normal mutated in place) */
  appendWarped(src: THREE.BufferGeometry, c: THREE.Color, warp: (p: THREE.Vector3, n: THREE.Vector3) => void) {
    const base = this.vcount;
    const p = src.getAttribute('position'); const n = src.getAttribute('normal');
    const v = new THREE.Vector3(); const vn = new THREE.Vector3();
    for (let i = 0; i < p.count; i++) {
      v.fromBufferAttribute(p, i); vn.fromBufferAttribute(n, i); warp(v, vn); vn.normalize();
      this.pos.push(v.x, v.y, v.z); this.nor.push(vn.x, vn.y, vn.z); this.col.push(c.r, c.g, c.b);
    }
    if (src.index) for (let i = 0; i < src.index.count; i++) this.idx.push(base + src.index.getX(i));
    else for (let i = 0; i < p.count; i++) this.idx.push(base + i);
  }
  /** append an indexed (or non-indexed) THREE geometry with a transform and flat colour */
  appendGeometry(src: THREE.BufferGeometry, m: THREE.Matrix4, c: THREE.Color) {
    const base = this.vcount;
    const p = src.getAttribute('position'); const n = src.getAttribute('normal');
    const nm = new THREE.Matrix3().getNormalMatrix(m);
    const v = new THREE.Vector3(); const vn = new THREE.Vector3();
    for (let i = 0; i < p.count; i++) {
      v.fromBufferAttribute(p, i).applyMatrix4(m); this.pos.push(v.x, v.y, v.z);
      vn.fromBufferAttribute(n, i).applyMatrix3(nm).normalize(); this.nor.push(vn.x, vn.y, vn.z);
      this.col.push(c.r, c.g, c.b);
    }
    if (src.index) for (let i = 0; i < src.index.count; i++) this.idx.push(base + src.index.getX(i));
    else for (let i = 0; i < p.count; i++) this.idx.push(base + i);
  }
}

const sub = (a: V3, b: V3): V3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const add = (a: V3, b: V3): V3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const mul = (a: V3, s: number): V3 => [a[0] * s, a[1] * s, a[2] * s];
const dot = (a: V3, b: V3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: V3, b: V3): V3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const len = (a: V3) => Math.hypot(a[0], a[1], a[2]);
const norm = (a: V3): V3 => { const l = len(a) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };

/**
 * Clay block on 8 corners. Corner index i = ix + 2*iy + 4*iz (ix,iy,iz in {0,1}).
 * rad = chamfer radius in world units, tilt = pillow normal tilt (0 = flat faces).
 */
function clayBlock(acc: Acc, C: V3[], rad: number, color: THREE.Color, tilt = 0.3) {
  const tri = (u: number, v: number, w: number): V3 => {
    const r: V3 = [0, 0, 0];
    for (let i = 0; i < 8; i++) {
      const wt = (i & 1 ? u : 1 - u) * ((i >> 1) & 1 ? v : 1 - v) * ((i >> 2) & 1 ? w : 1 - w);
      r[0] += C[i][0] * wt; r[1] += C[i][1] * wt; r[2] += C[i][2] * wt;
    }
    return r;
  };
  const L = [
    (len(sub(C[1], C[0])) + len(sub(C[3], C[2])) + len(sub(C[5], C[4])) + len(sub(C[7], C[6]))) / 4,
    (len(sub(C[2], C[0])) + len(sub(C[3], C[1])) + len(sub(C[6], C[4])) + len(sub(C[7], C[5]))) / 4,
    (len(sub(C[4], C[0])) + len(sub(C[5], C[1])) + len(sub(C[6], C[2])) + len(sub(C[7], C[3]))) / 4,
  ];
  const fr = L.map((l) => Math.min(0.42, rad / Math.max(l, 1e-4)));
  const center = tri(0.5, 0.5, 0.5);
  const base = acc.vcount;
  const P: V3[] = [];
  for (let a = 0; a < 3; a++) {
    const [b, c] = [0, 1, 2].filter((x) => x !== a);
    for (let s = 0; s < 2; s++) {
      const fp: V3[] = [];
      for (let jb = 0; jb < 2; jb++) for (let jc = 0; jc < 2; jc++) {
        const u: V3 = [0, 0, 0];
        u[a] = s; u[b] = jb ? 1 - fr[b] : fr[b]; u[c] = jc ? 1 - fr[c] : fr[c];
        fp.push(tri(u[0], u[1], u[2]));
      }
      let n = norm(cross(sub(fp[3], fp[0]), sub(fp[2], fp[1])));
      const fc = mul(add(add(fp[0], fp[1]), add(fp[2], fp[3])), 0.25);
      if (dot(n, sub(fc, center)) < 0) n = mul(n, -1);
      for (const p of fp) {
        const nn = norm(add(n, mul(norm(sub(p, fc)), tilt)));
        acc.pos.push(p[0], p[1], p[2]); acc.nor.push(nn[0], nn[1], nn[2]);
        acc.col.push(color.r, color.g, color.b); P.push(p);
      }
    }
  }
  const vid = (a: number, s: number, j: number[]) => {
    const [b, c] = [0, 1, 2].filter((x) => x !== a);
    return (a * 2 + s) * 4 + j[b] * 2 + j[c];
  };
  const T = (i: number, j: number, k: number) => {
    const n = cross(sub(P[j], P[i]), sub(P[k], P[i]));
    const cen = mul(add(add(P[i], P[j]), P[k]), 1 / 3);
    if (dot(n, sub(cen, center)) < 0) acc.idx.push(base + i, base + k, base + j);
    else acc.idx.push(base + i, base + j, base + k);
  };
  const Q = (i: number, j: number, k: number, l: number) => { T(i, j, k); T(i, k, l); };
  for (let a = 0; a < 3; a++) for (let s = 0; s < 2; s++) {
    const [b, c] = [0, 1, 2].filter((x) => x !== a);
    const j = (jb: number, jc: number) => { const r = [0, 0, 0]; r[b] = jb; r[c] = jc; return vid(a, s, r); };
    Q(j(0, 0), j(1, 0), j(1, 1), j(0, 1));
  }
  for (let a1 = 0; a1 < 3; a1++) for (let a2 = a1 + 1; a2 < 3; a2++) for (let s1 = 0; s1 < 2; s1++) for (let s2 = 0; s2 < 2; s2++) {
    const c = 3 - a1 - a2;
    const f1 = (jc: number) => { const r = [0, 0, 0]; r[a2] = s2; r[c] = jc; return vid(a1, s1, r); };
    const f2 = (jc: number) => { const r = [0, 0, 0]; r[a1] = s1; r[c] = jc; return vid(a2, s2, r); };
    Q(f1(0), f1(1), f2(1), f2(0));
  }
  for (let sx = 0; sx < 2; sx++) for (let sy = 0; sy < 2; sy++) for (let sz = 0; sz < 2; sz++) {
    T(vid(0, sx, [0, sy, sz]), vid(1, sy, [sx, 0, sz]), vid(2, sz, [sx, sy, 0]));
  }
}

/** axis-aligned (optionally Y-rotated, top-tapered) box corners */
function boxCorners(cx: number, cy: number, cz: number, w: number, h: number, d: number, rotY = 0, taperTop = 1, tiltX = 0): V3[] {
  const out: V3[] = [];
  const cs = Math.cos(rotY), sn = Math.sin(rotY);
  for (let i = 0; i < 8; i++) {
    const ix = i & 1, iy = (i >> 1) & 1, iz = (i >> 2) & 1;
    const k = iy ? taperTop : 1;
    let x = (ix ? 0.5 : -0.5) * w * k, z = (iz ? 0.5 : -0.5) * d * k;
    const y = (iy ? 0.5 : -0.5) * h;
    z += y * tiltX;
    out.push([cx + x * cs + z * sn, cy + y, cz - x * sn + z * cs]);
  }
  return out;
}

/** quad prism: 4 xy corners (BL, BR, TL, TR) extruded z0..z1 */
function prismCorners(bl: [number, number], br: [number, number], tl: [number, number], tr: [number, number], z0: number, z1: number): V3[] {
  const q = [bl, br, tl, tr];
  const out: V3[] = [];
  for (let i = 0; i < 8; i++) {
    const p = q[(i & 1) + 2 * ((i >> 1) & 1)];
    out.push([p[0], p[1], (i >> 2) & 1 ? z1 : z0]);
  }
  return out;
}

export function createKfbStoneBridgeField(opts: BridgeFieldOptions = {}): THREE.Group {
  const span = opts.span ?? 30;
  const riseRatio = opts.riseRatio ?? 0.35;
  const W = opts.halfWidth ?? 9.6;
  const abutLen = opts.abutLen ?? 8;
  const rng = mulberry32(opts.seed ?? 20261010);
  const rr = (a: number, b: number) => a + (b - a) * rng();

  const col = (hex: string) => new THREE.Color(hex);
  const M = KFB_BRIDGE_PALETTE.masonry.map(col);
  const RK = KFB_BRIDGE_PALETTE.rock.map(col);
  const GR = KFB_BRIDGE_PALETTE.grass.map(col);
  let lastTone = -1;
  const tone = (w: number[]) => {
    const pick = () => { let r = rng() * w.reduce((s, x) => s + x, 0); for (let i = 0; i < w.length; i++) { r -= w[i]; if (r <= 0) return i; } return w.length - 1; };
    let i = pick(); if (i === lastTone) i = pick();
    lastTone = i; return M[i];
  };
  const W_FACE = [0.34, 0.36, 0.2, 0.1];
  const W_RING = [0.18, 0.42, 0.3, 0.1];
  const W_DARK = [0.05, 0.25, 0.4, 0.3];
  const W_SLAB = [0.5, 0.42, 0.08, 0.0];
  const W_PIL = [0.48, 0.4, 0.12, 0.0];
  const W_CAP = [0.1, 0.3, 0.38, 0.22];

  const masonry = new Acc(), pavement = new Acc(), rocks = new Acc(), foliage = new Acc(), lanternFrame = new Acc(), lanternLight = new Acc();

  // ---- arch geometry ----
  const a = span / 2, f = span * riseRatio;
  const R = (a * a + f * f) / (2 * f);
  const ringT = 2.4;
  const crownI = -3.2; // intrados crown
  const yc = crownI - R;
  const Re = R + ringT;
  const ths = Math.asin(a / R);
  const Pi: [number, number] = [a, yc + R * Math.cos(ths)];
  const Pe: [number, number] = [Re * Math.sin(ths), yc + Re * Math.cos(ths)];
  const gap = 0.1, gapS = 0.08;
  const ext = (x: number) => (Math.abs(x) <= Re ? yc + Math.sqrt(Re * Re - x * x) : -1e9);

  const zWallOut = W - 0.1, zWallIn = zWallOut - 1.2;
  const zRingOut = W + 0.02, zRingIn = 7.85;
  const zPilOut = W + 0.35, zPilIn = W - 2.05;
  const xPilIn = a + 3.2, xPilOut = xPilIn + 2.9, xEnd = a + abutLen;
  const yFoot = Pi[1] - 0.8;
  const yBase = Pe[1] + gap;
  const capTop = 1.95, capBot = 1.4, parBot = 0.2, crownBot = crownI + ringT + gap; // 0.2..1.4 parapet
  const nLower = 7;
  const courses: { y0: number; y1: number }[] = [{ y0: crownBot, y1: parBot }];
  const ch = (crownBot - yBase) / nLower;
  for (let k = 0; k < nLower; k++) courses.push({ y0: crownBot - (k + 1) * ch, y1: crownBot - k * ch });
  const minH = 0.4;

  // ---- voussoir ring (both faces) + keystone ----
  const N = 15;
  const dTh = (2 * ths) / N;
  const gA = 0.05 / R;
  const polar = (th: number, r: number): [number, number] => [r * Math.sin(th), yc + r * Math.cos(th)];
  for (const side of [1, -1]) {
    for (let k = 0; k < N; k++) {
      const key = k === (N - 1) / 2;
      const widen = key ? dTh * 0.06 : 0;
      const t0 = -ths + k * dTh + gA - widen, t1 = -ths + (k + 1) * dTh - gA + widen;
      const ro = Re - 0.02;
      const zo = side * (zRingOut + (key ? 0.18 : 0)), zi = side * zRingIn;
      const q = [polar(t0, R), polar(t1, R), polar(t0, ro), polar(t1, ro)];
      const C: V3[] = [];
      for (let i = 0; i < 8; i++) { const p = q[(i & 1) + 2 * ((i >> 1) & 1)]; C.push([p[0], p[1], (i >> 2) & 1 ? zo : zi]); }
      clayBlock(masonry, C, 0.3, key ? M[0] : tone(W_RING), 0.32);
    }
  }
  // ---- barrel soffit (staggered courses between the face rings) ----
  for (let k = 0; k < N; k++) {
    const t0 = -ths + k * dTh + gA, t1 = -ths + (k + 1) * dTh - gA;
    const cuts = k % 2 === 0 ? [-1, -0.6, -0.2, 0.2, 0.6, 1] : [-1, -0.8, -0.4, 0, 0.4, 0.8, 1];
    for (let i = 0; i < cuts.length - 1; i++) {
      const z0 = cuts[i] * zRingIn + 0.04, z1 = cuts[i + 1] * zRingIn - 0.04;
      const q = [polar(t0, R + 0.03), polar(t1, R + 0.03), polar(t0, R + 1.3), polar(t1, R + 1.3)];
      const C: V3[] = [];
      for (let j = 0; j < 8; j++) { const p = q[(j & 1) + 2 * ((j >> 1) & 1)]; C.push([p[0], p[1], (j >> 2) & 1 ? z1 : z0]); }
      clayBlock(masonry, C, 0.26, tone(W_DARK), 0.3);
    }
  }
  // ---- skewbacks (springing stones) ----
  for (const sx of [1, -1]) {
    const zc = [-zRingOut, -4.8, 0, 4.8, zRingOut];
    for (let i = 0; i < 4; i++) {
      const z0 = zc[i] + 0.04, z1 = zc[i + 1] - 0.04;
      const m = (x: number): number => sx * x;
      // A: under first voussoir, top on the radial springing line
      const A = prismCorners([m(a - 0.4), yFoot], [m(Pe[0]), yFoot], [m(Pi[0]), Pi[1] - 0.05], [m(Pe[0]), Pe[1] - 0.05], z0, z1);
      clayBlock(masonry, A, 0.24, tone(W_DARK), 0.3);
      const B = prismCorners([m(Pe[0] + 0.06), yFoot], [m(xPilIn - 0.04), yFoot], [m(Pe[0] + 0.06), yBase - 0.02], [m(xPilIn - 0.04), yBase - 0.02], z0, z1);
      clayBlock(masonry, B, 0.24, tone(W_DARK), 0.3);
    }
  }

  // ---- spandrel + abutment face walls (chord-cut against the ring extrados) ----
  const xs = courses.map(({ y1 }) => {
    const y = y1 - minH - gap;
    if (y >= yc + Re) return 0;
    return Math.sqrt(Re * Re - (y - yc) * (y - yc));
  });
  const wallBlock = (sx: number, sz: number, xa: number, xb: number, ya0: number, yb0: number, y1: number, toneW: number[]) => {
    const z0 = sz > 0 ? zWallIn : -zWallOut, z1 = sz > 0 ? zWallOut : -zWallIn;
    const C = prismCorners([sx * xa, ya0], [sx * xb, yb0], [sx * xa, y1], [sx * xb, y1], z0, z1);
    clayBlock(masonry, C, 0.26, tone(toneW), 0.3);
  };
  for (const sz of [1, -1]) {
    for (let k = 0; k < courses.length; k++) {
      const { y0, y1 } = courses[k];
      const top = y1 - gapS / 2;
      const lowest = k === courses.length - 1;
      const support = lowest ? Pe[0] : xs[k + 1];
      const bottom = (x: number) => (Math.abs(x) < support - 1e-6 ? ext(x) + gap : y0 + gapS / 2);
      for (const sx of [1, -1]) {
        if (k === 0 && sx < 0) continue; // crown course is laid once across the full width
        const joints: number[] = [];
        const start = k === 0 ? -support : xs[k];
        if (k === 0) {
          const n = Math.max(1, Math.round((2 * support) / 3.0));
          for (let i = 0; i <= n; i++) joints.push(-support + (2 * support * i) / n);
        } else if (support - start >= 0.18) {
          const n = Math.max(1, Math.ceil((support - start) / 3.2));
          for (let i = 0; i <= n; i++) joints.push(start + ((support - start) * i) / n);
        } else joints.push(support);
        let x = support;
        let first = true;
        while (x < xPilIn - 0.01) {
          let l = first && k % 2 === 1 ? rr(1.2, 1.8) : rr(2.4, 3.6);
          first = false;
          if (xPilIn - (x + l) < 0.8) l = xPilIn - x;
          x += l; joints.push(Math.min(x, xPilIn));
        }
        if (k === 0) {
          // mirror the outer run onto the left side of the crown course
          const right = joints.filter((v) => v >= support - 1e-6);
          for (let i = right.length - 1; i >= 1; i--) {
            const xa = right[i - 1], xb = right[i];
            wallBlock(-1, sz, xa + gapS / 2, xb - gapS / 2, y0 + gapS / 2, y0 + gapS / 2, top, W_FACE);
          }
        }
        for (let i = 0; i < joints.length - 1; i++) {
          const xa = joints[i] + gapS / 2, xb = joints[i + 1] - gapS / 2;
          if (xb - xa < 0.12) continue;
          const ba = bottom(joints[i] + 1e-5);
          const bb = bottom(joints[i + 1] - 1e-5);
          // k===0 spans across x=0, so use the plain side multiplier 1
          wallBlock(k === 0 ? 1 : sx, sz, xa, xb, Math.min(ba, top - 0.25), Math.min(bb, top - 0.25), top, W_FACE);
        }
      }
    }
    // parapet course and cap stones (between pillars)
    {
      let x = -xPilIn; let l0 = rr(1.2, 2.0);
      while (x < xPilIn - 0.01) {
        let l = l0 || rr(2.4, 3.4); l0 = 0;
        if (xPilIn - (x + l) < 0.9) l = xPilIn - x;
        wallBlock(1, sz, x + gapS / 2, x + l - gapS / 2, parBot + gapS / 2, parBot + gapS / 2, capBot - gapS / 2, W_FACE);
        x += l;
      }
      x = -xPilIn;
      const nCap = Math.round((2 * xPilIn) / 2.6);
      const cl = (2 * xPilIn) / nCap;
      for (let i = 0; i < nCap; i++) {
        const z0 = sz > 0 ? zWallIn - 0.16 : -zWallOut - 0.16, z1 = sz > 0 ? zWallOut + 0.16 : -zWallIn + 0.16;
        const C = boxCorners(x + cl * (i + 0.5), (capBot + capTop) / 2, (z0 + z1) / 2, cl - 0.1, capTop - capBot, z1 - z0);
        clayBlock(masonry, C, 0.17, tone(W_CAP), 0.35);
      }
    }
  }

  // ---- end pillars (column from the rock footing to above the parapet) ----
  const pilCx = (xPilIn + xPilOut) / 2, pilW = xPilOut - xPilIn;
  const pilZc = (zPilIn + zPilOut) / 2, pilD = zPilOut - zPilIn;
  for (const sx of [1, -1]) for (const sz of [1, -1]) {
    const cx = sx * pilCx, cz = sz * pilZc;
    for (let k = courses.length - 1; k >= 0; k--) {
      const y0 = (k === courses.length - 1 ? yBase - 0.3 : courses[k].y0) + gapS / 2, y1 = courses[k].y1 - gapS / 2;
      const two = k % 2 === 0;
      if (two) {
        const split = rr(-0.3, 0.3);
        const xa = -pilW / 2, xm = split, xb = pilW / 2;
        clayBlock(masonry, boxCorners(cx + sx * (xa + xm) / 2, (y0 + y1) / 2, cz, xm - xa - gapS, y1 - y0, pilD), 0.26, tone(W_PIL), 0.3);
        clayBlock(masonry, boxCorners(cx + sx * (xm + xb) / 2, (y0 + y1) / 2, cz, xb - xm - gapS, y1 - y0, pilD), 0.26, tone(W_PIL), 0.3);
      } else {
        clayBlock(masonry, boxCorners(cx, (y0 + y1) / 2, cz, pilW - gapS, y1 - y0, pilD), 0.26, tone(W_PIL), 0.3);
      }
    }
    // above deck: three courses of two blocks, alternating split axis, plus a cap slab
    const ab = [parBot, 1.1, 2.0, 2.9];
    for (let i = 0; i < 3; i++) {
      const y0 = ab[i] + gapS / 2, y1 = ab[i + 1] - gapS / 2, ym = (y0 + y1) / 2;
      if (i % 2 === 0) {
        const s = rr(-0.2, 0.2);
        clayBlock(masonry, boxCorners(cx - pilW / 4 + s / 2, ym, cz, pilW / 2 + s - gapS, y1 - y0, pilD), 0.25, tone(W_PIL), 0.32);
        clayBlock(masonry, boxCorners(cx + pilW / 4 + s / 2, ym, cz, pilW / 2 - s - gapS, y1 - y0, pilD), 0.25, tone(W_PIL), 0.32);
      } else {
        clayBlock(masonry, boxCorners(cx, ym, cz - pilD / 4, pilW - gapS, y1 - y0, pilD / 2 - gapS), 0.25, tone(W_PIL), 0.32);
        clayBlock(masonry, boxCorners(cx, ym, cz + pilD / 4, pilW - gapS, y1 - y0, pilD / 2 - gapS), 0.25, tone(W_PIL), 0.32);
      }
    }
    clayBlock(masonry, boxCorners(cx, 2.9 + 0.19, cz, pilW + 0.3, 0.38, pilD + 0.3), 0.15, tone(W_CAP), 0.35);
    addLantern(lanternFrame, lanternLight, cx, 2.9 + 0.38, cz, (5.82 - 3.28) / 2.87);
  }

  // ---- hidden backing core: fills joints so no background shows through (darkest masonry tone) ----
  {
    const coreTop = -0.3;
    const xsCore: number[] = [];
    for (let i = 0; i <= 10; i++) xsCore.push((Pe[0] * i) / 10);
    xsCore.push(xPilOut - 0.2);
    const cb = (x: number) => (x <= Pe[0] + 1e-6 ? ext(x) - 0.35 : yBase - 0.2);
    for (const sx of [1, -1]) for (let i = 0; i < xsCore.length - 1; i++) {
      const xa = xsCore[i], xb = xsCore[i + 1];
      const C = prismCorners([sx * xa, cb(xa)], [sx * xb, i === xsCore.length - 2 ? yBase - 0.2 : cb(xb)], [sx * xa, coreTop], [sx * xb, coreTop], -zWallOut + 0.25, zWallOut - 0.25);
      clayBlock(masonry, C, 0.02, M[3], 0);
    }
    for (const sz of [1, -1]) clayBlock(masonry, boxCorners(0, 0.82, sz * (zWallIn + zWallOut) / 2, 2 * xPilIn + 0.2, 1.3, zWallOut - zWallIn - 0.4), 0.02, M[3], 0);
    for (const sx of [1, -1]) for (const sz of [1, -1]) clayBlock(masonry, boxCorners(sx * pilCx, (yBase + 2.9) / 2, sz * pilZc, pilW - 0.4, 2.9 - yBase, pilD - 0.5), 0.02, M[3], 0);
  }

  // ---- deck: bed + rounded pavement slabs (flat, gradient 0) ----
  clayBlock(masonry, boxCorners(0, -0.42, 0, 2 * xPilOut, 0.25, 2 * zWallIn), 0.05, M[3], 0);
  const roadZ = 6.25;
  const rows = 7;
  for (let r = 0; r < rows; r++) {
    const z0 = -roadZ + (2 * roadZ * r) / rows, z1 = -roadZ + (2 * roadZ * (r + 1)) / rows;
    let x = -xPilOut; let l = rr(0.6, 2.4);
    while (x < xPilOut - 0.01) {
      if (xPilOut - (x + l) < 0.7) l = xPilOut - x;
      const C = boxCorners(x + l / 2, -0.22, (z0 + z1) / 2, l - 0.1, 0.44, z1 - z0 - 0.1);
      clayBlock(pavement, C, 0.15, tone(W_SLAB), 0.3);
      x += l; l = rr(2.2, 3.4);
    }
  }
  // sidewalks (raised 0.2) between pillars, narrower strip beside the pillars
  for (const sz of [1, -1]) {
    const runs: [number, number, number][] = [[-xPilIn, xPilIn, zWallIn], [-xPilOut, -xPilIn, zPilIn], [xPilIn, xPilOut, zPilIn]];
    for (const [xa, xb, zo] of runs) {
      const n = Math.max(1, Math.round((xb - xa) / 2.6));
      const l = (xb - xa) / n;
      for (let i = 0; i < n; i++) {
        const zc = sz * (roadZ + zo) / 2;
        const C = boxCorners(xa + l * (i + 0.5), -0.15, zc, l - 0.1, 0.7, zo - roadZ - 0.1);
        clayBlock(pavement, C, 0.15, tone(W_SLAB), 0.3);
      }
    }
  }

  // ---- rock footing: rounded grey boulders under both abutments + outer rock stack ----
  const rockGeo = new RoundedBoxGeometry(1, 1, 1, 2, 0.24);
  const rock = (cx: number, cy: number, cz: number, w: number, h: number, d: number) => {
    const rot = rr(-0.12, 0.12), taper = rr(0.8, 0.9), cs = Math.cos(rot), sn = Math.sin(rot);
    const k = Math.min(w, h, d);
    rocks.appendWarped(rockGeo, RK[rng() < 0.5 ? 0 : 1], (p, n) => {
      // keep the rounding radius ~0.24*min(w,h,d) by scaling the inner box, not the fillet
      const rW = 0.3 * k;
      const sx = (v: number, L: number) => { const q = Math.abs(v); return Math.sign(v) * (q <= 0.26 ? (q / 0.26) * (L / 2 - rW) : L / 2 - rW + ((q - 0.26) / 0.24) * rW); };
      let x = sx(p.x, w), y = sx(p.y, h), z = sx(p.z, d);
      const t = 1 + (taper - 1) * (y / h + 0.5);
      x *= t; z *= t;
      p.set(cx + x * cs + z * sn, cy + y, cz - x * sn + z * cs);
      n.set(n.x * cs + n.z * sn, n.y, -n.x * sn + n.z * cs);
    });
  };
  for (const sx of [1, -1]) {
    const zs = [-6.5, 0, 6.5];
    for (const z of zs) {
      rock(sx * (a + 0.7 + rr(-0.2, 0.2)), (yFoot - 3.0 + yFoot) / 2 - 0.05, z + rr(-0.3, 0.3), rr(4.2, 4.8), 3.1, rr(6.6, 7.2));
      rock(sx * ((xPilIn + xEnd) / 2 + 0.4), (-17.6 + yBase + 0.15) / 2, z + rr(-0.3, 0.3), xEnd - xPilIn + 1.2, yBase + 0.15 + 17.6, rr(6.6, 7.2));
      rock(sx * ((xPilOut + xEnd) / 2 + 0.2), -9.3, z + rr(-0.2, 0.2), xEnd - xPilOut + 0.7, 5.6, rr(6.6, 7.0));
      rock(sx * ((xPilOut + xEnd) / 2 + 0.1), -4.0, z + rr(-0.3, 0.3), xEnd - xPilOut + 0.5, 5.4, rr(6.4, 7.0));
    }
  }

  // ---- grass caps on the outer abutment rocks (thick, rounded clay lip) + drapes ----
  const grassCapGeo = new RoundedBoxGeometry(xEnd - xPilOut + 0.75, 1.8, 2 * (W + 0.45), 3, 0.8);
  const m4 = new THREE.Matrix4();
  for (const sx of [1, -1]) {
    m4.makeTranslation(sx * ((xPilOut + xEnd + 0.75) / 2 - 0.05), 0.08 - 1.8 / 2, 0);
    foliage.appendGeometry(grassCapGeo, m4, GR[0]);
  }
  const blob = new THREE.SphereGeometry(1, 8, 6);
  const drape = (x: number, y: number, z: number, sx: number, sy: number, sz: number, c: THREE.Color) => {
    m4.compose(new THREE.Vector3(x, y, z), new THREE.Quaternion(), new THREE.Vector3(sx, sy, sz));
    foliage.appendGeometry(blob, m4, c);
  };
  for (const sx of [1, -1]) {
    const xo = sx * (xEnd + 0.62);
    drape(xo - sx * 0.1, -1.7, rr(-7, -5), 0.7, 1.1, 2.2, GR[0]);
    drape(xo - sx * 0.1, -1.55, rr(-1, 1), 0.6, 0.8, 1.6, GR[0]);
    drape(xo - sx * 0.1, -1.8, rr(4.5, 6.5), 0.7, 1.2, 2.0, GR[0]);
    drape(sx * (xPilOut + 1.5), -1.75, W + 0.45, 1.6, 1.15, 0.7, GR[0]);
    drape(sx * (xEnd + 0.1), -2.1, W + 0.2, 0.9, 1.3, 0.8, GR[0]);
    drape(sx * (xPilOut + 1.2), -1.65, -(W + 0.45), 1.4, 1.0, 0.7, GR[0]);
  }

  // ---- ivy: 3 chunky clay clusters of big blobby leaves ----
  const leaf = makeLeafGeometry();
  const ivy = (x: number, y: number, z: number, face: 1 | -1, trail: number, size: number) => {
    const basis = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), face > 0 ? 0 : Math.PI);
    const put = (lx: number, ly: number, spin: number, s: number, c: THREE.Color, out: number) => {
      const q = basis.clone()
        .multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 0, 1), spin))
        .multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), 0.5));
      const p = new THREE.Vector3(lx, ly, out).applyQuaternion(basis).add(new THREE.Vector3(x, y, z));
      m4.compose(p, q, new THREE.Vector3(s, s, s));
      foliage.appendGeometry(leaf, m4, c);
    };
    const n = 7;
    for (let i = 0; i < n; i++) {
      const ph = (i / n) * Math.PI * 2 + rr(-0.25, 0.25);
      const s = size * rr(0.9, 1.15);
      put(Math.cos(ph) * 0.8 * size, Math.sin(ph) * 0.7 * size, ph - Math.PI / 2, s, GR[i % 2], 0.45 + 0.15 * (i % 2));
    }
    put(0, 0.1, rr(-0.3, 0.3), size * 1.2, GR[0], 0.8);
    for (let i = 0; i < trail; i++) {
      put(rr(-0.35, 0.35) * size, -(1.35 + i * 1.05) * size, Math.PI + rr(-0.7, 0.7), size * rr(0.75, 0.95), GR[(i + 1) % 2], 0.3);
    }
  };
  ivy(-a - 1.5, -3.0, zWallOut, 1, 3, 1.3);
  ivy(pilCx + 0.1, 1.1, zPilOut, 1, 3, 1.15);
  ivy(a + 1.4, -4.4, -zWallOut, -1, 2, 1.25);

  // ---- assemble ----
  const clayMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.88, metalness: 0 });
  const lightMat = new THREE.MeshStandardMaterial({ color: KFB_BRIDGE_PALETTE.lanternLight, emissive: '#ffbf5a', emissiveIntensity: 0.85, roughness: 0.6 });
  const g = new THREE.Group();
  g.name = 'KfbStoneBridgeField';
  const parts: [string, Acc, THREE.Material][] = [
    ['masonry', masonry, clayMat], ['pavement', pavement, clayMat], ['rocks', rocks, clayMat],
    ['foliage', foliage, clayMat], ['lanternFrame', lanternFrame, clayMat], ['lanternLight', lanternLight, lightMat],
  ];
  for (const [name, acc, mat] of parts) {
    const mesh = new THREE.Mesh(acc.build(), mat);
    mesh.name = name;
    mesh.castShadow = opts.castShadow ?? true;
    mesh.receiveShadow = opts.receiveShadow ?? true;
    g.add(mesh);
  }
  g.userData.kfbBridgeField = {
    units: 'K2 lab', figureH: 3.64, span, rise: f, intradosRadius: +R.toFixed(3), springingY: +Pi[1].toFixed(3),
    deckTopY: 0, gradient: 0, deckHalfWidth: W, roadHalfWidth: roadZ, parapetTop: capTop, lanternTop: 5.82,
    ends: { a: [-xEnd - 0.7, 0, 0], b: [xEnd + 0.7, 0, 0] },
    driveCollider: { min: [-xEnd - 0.7, -0.45, -roadZ], max: [xEnd + 0.7, 0, roadZ] },
  };
  return g;
}

function makeLeafGeometry(): THREE.BufferGeometry {
  // teardrop clay leaf: flattened low-poly sphere, tip along +y
  const g = new THREE.SphereGeometry(1, 7, 5);
  const p = g.getAttribute('position');
  for (let i = 0; i < p.count; i++) {
    let x = p.getX(i), y = p.getY(i), z = p.getZ(i);
    if (y > 0) { const k = 1 - 0.3 * y; x *= k; z *= k; y *= 1 + 0.22 * y; }
    p.setXYZ(i, x * 0.66, y * 0.72 + 0.3, z * 0.26);
  }
  g.computeVertexNormals();
  return g;
}

let lanternGeo: { post: THREE.CylinderGeometry; roof: THREE.ConeGeometry; finial: THREE.SphereGeometry } | null = null;
function addLantern(frame: Acc, light: Acc, x: number, y0: number, z: number, k = 1) {
  // all lantern parts are authored for k=1 (2.87 tall) and scaled about the base
  const fA = new Acc(), lA = new Acc(); const y = 0; const X = 0, Z = 0;
  const green = new THREE.Color(KFB_BRIDGE_PALETTE.lanternGreen);
  const warm = new THREE.Color(KFB_BRIDGE_PALETTE.lanternLight);
  lanternGeo ??= { post: new THREE.CylinderGeometry(0.25, 0.3, 0.72, 8), roof: new THREE.ConeGeometry(0.84, 0.5, 4), finial: new THREE.SphereGeometry(0.17, 8, 5) };
  const m = new THREE.Matrix4();
  clayBlock(fA, boxCorners(X, y + 0.13, Z, 1.1, 0.26, 1.1), 0.08, green, 0.3);
  m.makeTranslation(X, y + 0.26 + 0.36, Z); fA.appendGeometry(lanternGeo.post, m, green);
  clayBlock(fA, boxCorners(X, y + 1.04, Z, 0.95, 0.16, 0.95), 0.06, green, 0.3);
  clayBlock(lA, boxCorners(X, y + 1.56, Z, 0.84, 0.9, 0.84), 0.1, warm, 0.2);
  for (const dx of [-1, 1]) for (const dz of [-1, 1]) clayBlock(fA, boxCorners(X + dx * 0.43, y + 1.56, Z + dz * 0.43, 0.16, 0.92, 0.16), 0.04, green, 0.2);
  clayBlock(fA, boxCorners(X, y + 2.07, Z, 1.2, 0.14, 1.2), 0.06, green, 0.3);
  m.makeRotationY(Math.PI / 4).setPosition(X, y + 2.13 + 0.25, Z); fA.appendGeometry(lanternGeo.roof, m, green);
  m.makeTranslation(X, y + 2.7, Z); fA.appendGeometry(lanternGeo.finial, m, green);
  const mk = new THREE.Matrix4().makeScale(k, k, k).setPosition(x, y0, z);
  const tmpG = fA.build(), tmpL = lA.build();
  const c0 = new THREE.Color(); // vertex colours are carried per vertex; append with colour from attribute
  for (const [src, dst] of [[tmpG, frame], [tmpL, light]] as [THREE.BufferGeometry, Acc][]) {
    const base = dst.vcount; const p = src.getAttribute('position'), n = src.getAttribute('normal'), c = src.getAttribute('color');
    const v = new THREE.Vector3();
    for (let i = 0; i < p.count; i++) {
      v.fromBufferAttribute(p, i).applyMatrix4(mk); dst.pos.push(v.x, v.y, v.z);
      dst.nor.push(n.getX(i), n.getY(i), n.getZ(i)); c0.fromBufferAttribute(c, i); dst.col.push(c0.r, c0.g, c0.b);
    }
    for (let i = 0; i < src.index!.count; i++) dst.idx.push(base + src.index!.getX(i));
  }
}
